import type { Addon, BetterDiscord, GitHub, OptionalMeta, RequiredMeta, Vencord } from './types.js';

export interface Config {
	meta: RequiredMeta & OptionalMeta;

	/**
	 * The relative entry point to the main theme.
	 *
	 * @default `src/main.scss`
	 */
	main?: string;

	/**
	 * The relative entry point to the css file containing all your public facing variables.
	 *
	 * @default `src/root.scss`
	 */
	root?: string;

	/**
	 * The GitHub profile and repo to point to.
	 */
	github?: GitHub;

	/**
	 * Any "external" css files that should be compiled with your theme.
	 *
	 * Providing the `dev` flag will auto add your addon to the end of your dev file, no need to `@import` to manually.
	 */
	addons?: Addon[];

	/** Options for BetterDiscord */
	betterdiscord?: BetterDiscord;

	/** Options for Vencord */
	vencord?: Vencord;

	/** Options for PrettyFluxer **/
	prettyfluxer?: PrettyFluxer;
	
	/**
	 * Generate an additional theme file that contains the entire CSS and doesn't contain the `@import url('...');`
	 * Much like the dev theme file, but follows the `dist` flags.
	 *
	 * The file generated will look like: `CoolTheme.static.theme.css`.
	 *
	 * This will mean users will rely on the BetterDiscord updater to update their theme.
	 */
	static?: boolean;
}
